using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
namespace LWS.TruckSports.Editor {
public static class SportsExpansionFront {
 public static readonly string[] Keys={"billiards","hockey","bowling","airhockey","wallball","cornhole","cheese","dock","keepaway","curling","basejump"};
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);var f=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();var page=f.pages[1].transform;
  string[] names={"BILLIARDS","HOCKEY","BOWLING","AIR HOCKEY","WALLBALL","CORNHOLE","CHEESE","DOCK DIVING","KEEPAWAY","CURLING","BASE JUMPING"};
  string[] titles={"TRUCK BILLIARDS","TRUCK ICE HOCKEY","TRUCK BOWLING","TRUCK AIR HOCKEY","TRUCK WALLBALL","TRUCK CORNHOLE","HARDCORE TRUCK\nCHEESE ROLLING","TRUCK DOCK DIVING","TRUCK KEEPAWAY","TRUCK CURLING","TRUCK BASE JUMPING"};
  string[] descriptions={"8-ball bumper precision.\nRacks, series or solo practice.","Articulated sticks. Heavy hits.\nContinuous 3v3 on ice.","Four simultaneous lanes.\nPhysical pins and spinouts.","Your truck is the paddle.\nRounded corners · first to 7.","Return it off the front wall.\nTeams of 1–4 · uneven teams.","Drive. Trampoline. Fly.\nFour simultaneous courses.","Catch cheese. Dodge sheep.\n1–4 players · chaotic hill.","Time the leap. Split the cab.\n1–8 · multiangle replays.","Steal possession. Explode.\n2–4 · cumulative time wins.","Physical truck-stones.\n1–4 per team · draws & guards.","Helicopter drop. Deploy. Land.\nFour trucks · shared wild weather."};
  var template=page.Find("CORNHOLE Sport Card");for(int i=0;i<names.Length;i++){var card=page.Find(names[i]+" Sport Card");if(card==null){card=UnityEngine.Object.Instantiate(template.gameObject,page).transform;card.name=names[i]+" Sport Card";}float x=(i%4-1.5f)*345,y=155-i/4*220;var rect=card.GetComponent<RectTransform>();rect.sizeDelta=new Vector2(330,205);rect.anchoredPosition=new Vector2(x,y);foreach(Transform child in card)if(child.name!="Sport"&&child.name!="Description")child.gameObject.SetActive(false);var title=card.Find("Sport").GetComponent<TMP_Text>();title.text=titles[i];title.rectTransform.sizeDelta=new Vector2(312,58);title.rectTransform.anchoredPosition=new Vector2(0,64);title.fontSizeMax=i==6?22:25;title.fontSizeMin=19;var d=card.Find("Description").GetComponent<TMP_Text>();d.text=descriptions[i];d.rectTransform.sizeDelta=new Vector2(310,67);d.rectTransform.anchoredPosition=new Vector2(0,-1);d.fontSizeMax=19;d.fontSizeMin=17;
   var actions=page.GetComponentsInChildren<SportsMenuAction>(true).Where(a=>a.action==Keys[i]||i==0&&a.action=="practice").ToArray();if(actions.Length==0)SportsUIAuthoring.Button(page,"PLAY",Keys[i],Vector2.zero,new Vector2(300,40));foreach(var a in page.GetComponentsInChildren<SportsMenuAction>(true).Where(a=>a.action==Keys[i]||i==0&&a.action=="practice")){var b=a.GetComponent<RectTransform>();b.sizeDelta=new Vector2(i==0?145:300,42);b.anchoredPosition=new Vector2(x+(i==0?(a.action=="practice"?76:-76):0),y-78);a.button.buttonText=a.action=="practice"?"PRACTICE":i==0?"MATCH":"PLAY";a.button.normalTextObj.text=a.button.buttonText;a.button.normalTextObj.rectTransform.sizeDelta=b.sizeDelta-new Vector2(8,4);a.button.normalTextObj.fontSizeMax=19;a.button.normalTextObj.fontSizeMin=16;}}
  var back=page.GetComponentsInChildren<SportsMenuAction>(true).First(a=>a.action=="back").GetComponent<RectTransform>();back.anchoredPosition=new Vector2(0,-417);back.sizeDelta=new Vector2(460,43);page.Find("Subtitle").GetComponent<TMP_Text>().text="Eleven sports · Offline local play · Shared settings";f.pages[0].transform.Find("Collection").GetComponent<TMP_Text>().text="ELEVEN SPORTS. ONE TRUCK COLLECTION.\nLocal humans, shared controllers and autonomous AI.";
  f.pages[2].transform.Find("Guidance").GetComponent<TMP_Text>().text="DRIVE INTO THE GAME\nBilliards, ice hockey, air hockey, bowling, wallball, cornhole and cheese rolling retain their own rules and feel. Dock Diving, Keepaway, Curling and Base Jumping add four new physical events. Choose a sport, set names/colors/devices and start. Every sport has a complete HOW TO PLAY screen.\n\nOFFLINE INPUT\nUse separate controllers, independent keyboard clusters, AI, or share one controller’s left/right sticks where offered. A whole controller has one owner; separate sticks can have separate owners. Action bindings are shown per participant. Opposite throttle brakes before reversing.\n\nPAUSE / RECONNECT\nEsc or assigned Start pauses. Disconnected sources preserve the match; reconnect or explicitly replace them, release controls and freshly confirm. Rematches retain the setup. Shared settings control audio, display, steering sensitivity and vibration.\n\nNo online services or accounts required.";
  EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("TS_EXPANSION_FRONT eleven playable sports");}
 public static void Validate(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);var f=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();foreach(var key in Keys)if(f.pages[1].GetComponentsInChildren<SportsMenuAction>(true).Count(a=>a.action==key)!=1)throw new Exception("Front entry count "+key);Debug.Log("TS_EXPANSION_FRONT_VALIDATED entries="+Keys.Length);}
 public static void FinishBuild(){SportsExpansionAuthoring.ValidateExisting();LWS.TruckDockDiving.Editor.DockAuthoring.Validate();LWS.TruckKeepaway.Editor.KeepawayAuthoring.Validate();LWS.TruckCurling.Editor.CurlingAuthoring.Validate();LWS.TruckBaseJumping.Editor.BaseJumpAuthoring.Validate();Upgrade();Validate();SportsBuilder.Build();SportsExpansionAuthoring.InspectBuild();}
}
}
